/* ═══════════════════════════════════════════════════════════
   BLLUE_UI.js · o céu como interface
   ───────────────────────────────────────────────────────────
   UI não é tela. UI é CLIMA. Reage ao estado como o céu
   reage ao barômetro. O usuário não vê pixels — vê ATMOSFERA.
   ═══════════════════════════════════════════════════════════ */
class BllueUI {
  constructor(hostSelector = "body"){
    this.host = document.querySelector(hostSelector) || document.body;
    this.clima = "equilibrio";     // noite | alvorada | dia | entardecer | equilibrio
    this.pressao = 0.5;            // 0 = tempestade · 1 = céu limpo
    this._estilos();
  }

  _estilos(){
    if (document.getElementById("bllue-ui-style")) return;
    const s = document.createElement("style");
    s.id = "bllue-ui-style";
    s.textContent = `
      body.bllue-noite       { --bllue-c: #1e2c57; --bllue-s: #0a1430; }
      body.bllue-alvorada    { --bllue-c: #ff8c66; --bllue-s: #4a1e4d; }
      body.bllue-dia         { --bllue-c: #7dd3fc; --bllue-s: #a5e0ff; }
      body.bllue-entardecer  { --bllue-c: #f59e0b; --bllue-s: #7c2d12; }
      body.bllue-equilibrio  { --bllue-c: #4a6aff; --bllue-s: #1a1f40; }

      body{
        background:
          radial-gradient(circle at 30% 20%,
            var(--bllue-c, #4a6aff) 0%, transparent 40%),
          radial-gradient(circle at 70% 80%,
            var(--bllue-s, #1a1f40) 0%, transparent 60%),
          #05070a;
        transition:
          background var(--bllue-transicao, 1.4s) ease,
          color .6s ease;
      }

      .bllue-vento{
        position: fixed; inset: 0;
        pointer-events: none;
        opacity: 0;
        background: radial-gradient(circle at 50% 50%,
          var(--bllue-c, #4a6aff) 0%, transparent 70%);
        transition: opacity var(--bllue-transicao, 1.4s) ease;
      }
      body.bllue-tempestade .bllue-vento{ opacity: .28; }
    `;
    document.head.appendChild(s);

    const vento = document.createElement("div");
    vento.className = "bllue-vento";
    document.body.appendChild(vento);
    this.vento = vento;
  }

  /** Define o clima da UI com base no estado emocional do sistema. */
  assoprar(clima){
    const validos = ["noite","alvorada","dia","entardecer","equilibrio"];
    if (!validos.includes(clima)) clima = "equilibrio";
    if (clima === this.clima) return;
    document.body.classList.remove(...validos.map(v => `bllue-${v}`));
    document.body.classList.add(`bllue-${clima}`);
    this.clima = clima;
    this.host.dispatchEvent(new CustomEvent("bllue:clima", {
      bubbles:true, detail:{ clima, ts:Date.now() }
    }));
  }

  /** Ajusta a pressão atmosférica — determina "tempestade" ou "calmaria". */
  barometro(pressao){
    this.pressao = Math.max(0, Math.min(1, Number(pressao) || 0));
    document.body.classList.toggle("bllue-tempestade", this.pressao < 0.3);
    document.body.style.setProperty("--bllue-transicao",
      `${(2.2 - this.pressao * 1.8).toFixed(2)}s`);
  }

  /** Roda o dia inteiro em minutos — 24h de céu em 24s. */
  async cicloRapido(duracaoSeg = 24){
    const climas = ["noite","alvorada","dia","entardecer"];
    const passo = (duracaoSeg * 1000) / climas.length;
    for (const c of climas){
      this.assoprar(c);
      await new Promise(r => setTimeout(r, passo));
    }
    return "ciclo completo";
  }

  status(){
    return { clima:this.clima, pressao:this.pressao };
  }
}

window.BLLUE = new BllueUI("body");
console.log("[Bllue] céu interface online ·", BLLUE.status());
